		"https://www.edx.org/",
		"https://www.coursera.org/articles",
	}

	maxDepth := 3       // crawl deeper
	maxPages := 50      // collect more pages
	delay := 2 * time.Second

	var pages []Page
	pageCount := 0

	c := colly.NewCollector(
		colly.MaxDepth(maxDepth),
	)

	c.Limit(&colly.LimitRule{
		DomainGlob:  "*",
		Delay:       delay,
		RandomDelay: delay,
	})

	visited := make(map[string]bool)

	shouldStop := func() bool {
		return pageCount >= maxPages
	}

	c.OnHTML("html", func(e *colly.HTMLElement) {
		url := e.Request.URL.String()

		if visited[url] || shouldStop() {
			return
		}

		title := e.ChildText("title")

		var paragraphs []string
		e.DOM.Find("p").Each(func(_ int, s *goquery.Selection) {
			text := strings.TrimSpace(s.Text())
			if text != "" {
				paragraphs = append(paragraphs, text)
			}
		})
		content := strings.Join(paragraphs, " ")

		if len(content) > 100 {
			page := Page{
				URL:     url,
				Title:   title,
				Content: content,
			}
			pages = append(pages, page)
			visited[url] = true
			pageCount++

			fmt.Printf("✅ [%d/%d] Crawled: %s\n", pageCount, maxPages, title)
		}
	})

	c.OnHTML("a[href]", func(e *colly.HTMLElement) {
		if shouldStop() {
			return
		}

		link := e.Attr("href")

		// Skip Wikipedia admin / special pages
		if strings.Contains(link, ":") && strings.HasPrefix(e.Request.URL.Host, "en.wikipedia.org") {
			return
		}

		// Visit relative or absolute links
		if strings.HasPrefix(link, "/wiki/") || strings.HasPrefix(link, "http") {
			err := e.Request.Visit(e.Request.AbsoluteURL(link))
			if err != nil && !strings.Contains(err.Error(), "already visited") && !strings.Contains(err.Error(), "Max depth limit") {
				fmt.Printf("⚠️ Visit error: %v\n", err)
			}
		}
	})

	c.OnError(func(r *colly.Response, err error) {
		fmt.Printf("❌ Error visiting %s: %v\n", r.Request.URL, err)
	})

	c.OnRequest(func(r *colly.Request) {
		if !shouldStop() {
			fmt.Println("🔍 Visiting:", r.URL)
		}
	})

	fmt.Println("🚀 Starting crawl...")
	fmt.Printf("📊 Target: %d pages, Max depth: %d\n\n", maxPages, maxDepth)

	for _, url := range startURLs {
		if shouldStop() {
			break
		}
		err := c.Visit(url)
		if err != nil {
			fmt.Printf("⚠️ Initial visit error: %v\n", err)
		}
	}

	if len(pages) == 0 {
		fmt.Println("⚠️ No pages were crawled!")
		return
	}

	data, err := json.MarshalIndent(pages, "", "  ")
	if err != nil {
		fmt.Printf("❌ Error marshaling JSON: %v\n", err)
		return
	}

	err = os.WriteFile("crawled_data.json", data, 0644)
	if err != nil {
		fmt.Printf("❌ Error saving file: %v\n", err)
		return
	}

	fmt.Printf("\n🎉 Crawling complete!\n")
	fmt.Printf("📦 Collected %d pages\n", len(pages))
	fmt.Printf("💾 Saved to: crawled_data.json\n")
}
